export class GameAudio{
 constructor(){this.ctx=null;this.muted=false;this.volume=.5;}
 start(){if(this.ctx){this.ctx.resume();return;}try{this.ctx=new (window.AudioContext||window.webkitAudioContext)();this.master=this.ctx.createGain();this.master.gain.value=this.muted?0:this.volume;this.master.connect(this.ctx.destination);this.noiseBuffer=this.ctx.createBuffer(1,this.ctx.sampleRate*2,this.ctx.sampleRate);const d=this.noiseBuffer.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;const source=this.ctx.createBufferSource();source.buffer=this.noiseBuffer;source.loop=true;const f=this.ctx.createBiquadFilter(),g=this.ctx.createGain();f.type='lowpass';f.frequency.value=400;g.gain.value=.025;source.connect(f).connect(g).connect(this.master);source.start();}catch{}}
 setMuted(v){this.muted=v;if(this.master)this.master.gain.setTargetAtTime(v?0:this.volume,this.ctx.currentTime,.03);}
 tone(freq=500,duration=.1,type='sine',volume=.1){if(!this.ctx)return;const t=this.ctx.currentTime,o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type=type;o.frequency.setValueAtTime(freq,t);o.frequency.exponentialRampToValueAtTime(Math.max(30,freq*.6),t+duration);g.gain.setValueAtTime(volume,t);g.gain.exponentialRampToValueAtTime(.001,t+duration);o.connect(g).connect(this.master);o.start(t);o.stop(t+duration);}
 noise(duration=.2,volume=.3,cutoff=2000,pan=0){if(!this.ctx)return;const t=this.ctx.currentTime,s=this.ctx.createBufferSource(),f=this.ctx.createBiquadFilter(),g=this.ctx.createGain(),p=this.ctx.createStereoPanner();s.buffer=this.noiseBuffer;f.type='lowpass';f.frequency.value=cutoff;g.gain.setValueAtTime(volume,t);g.gain.exponentialRampToValueAtTime(.001,t+duration);p.pan.value=Math.max(-1,Math.min(1,pan));s.connect(f).connect(g).connect(p).connect(this.master);s.start(t);s.stop(t+duration);}
 event(e,player){if(e.type==='shot'){const d=Math.hypot(e.from.x-player.x,e.from.z-player.z),v=e.enemy?Math.max(.03,.4-d*.008):.5;this.noise(e.weapon==='marksman'?.28:.18,v,e.weapon==='carbine'?3100:2400,(e.from.x-player.x)/30);this.tone(e.weapon==='marksman'?65:e.enemy?85:105,.16,'triangle',v*.45);setTimeout(()=>this.noise(.15,v*.18,800),85);}if(e.type==='reload'){this.noise(.12,.13,1800);setTimeout(()=>this.noise(.12,.12,2800),1200);}if(e.type==='loaded')this.noise(.12,.25,3200);if(e.type==='melee')this.noise(.14,.2,350);if(e.type==='hurt')this.tone(60,.18,'sine',.23);if(['objective','pickup','healed'].includes(e.type)){this.tone(620,.12);setTimeout(()=>this.tone(900,.2),100);}if(e.type==='radio'||e.type==='reinforcement'){this.noise(.2,.08,1100);this.tone(1100,.1,'square',.04);}if(e.type==='smoke')this.noise(.8,.2,850);if(e.type==='decoy')this.tone(430,.12,'triangle',.2);}
}
